      SUBROUTINE RDFIND(STRING)C---- FIND NEXT CHARACTER OCCURRING IN "STRING"C-------------------------------------------------------------------      CHARACTER*(*)   STRINGC-------------------------------------------------------------------      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'RDBUFF.CIN'C-------------------------------------------------------------------   10 ITEM = KLINE(ICOL)      IF ((.NOT.ENDFIL) .AND. (INDEX(STRING,ITEM) .EQ. 0)) THEN        CALL RDNEXT        IF (.NOT. ENDFIL) GO TO 10      ENDIF      RETURNC-------------------------------------------------------------------      END